  `tenor` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `value` decimal(24,8) DEFAULT NULL,
  `yield_rate` decimal(18,8) DEFAULT NULL,
  `credit_spread` decimal(18,8) DEFAULT NULL,
  `volatility` decimal(18,8) DEFAULT NULL,
  `unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
