--
-- Table structure for table `positions`
--

DROP TABLE IF EXISTS `positions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `positions` (
  `position_id` int NOT NULL,
  `product_id` int DEFAULT NULL,
  `product_Code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `position_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `as_of_datetime` datetime DEFAULT NULL,
  `account_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `segment` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `currency_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `balance_amount` decimal(20,2) DEFAULT NULL,
  `interest_rate` decimal(18,8) DEFAULT NULL,
  `rate_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `spread` decimal(18,8) DEFAULT NULL,
  `start_date` datetime DEFAULT NULL,
  `maturity_date` datetime DEFAULT NULL,
  `next_repricing_date` datetime DEFAULT NULL,
  `repricing_frequency` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fair_value` decimal(20,2) DEFAULT NULL,
  `ecl_amount` decimal(20,2) DEFAULT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`position_id`),
  KEY `idx_positions_product_id` (`product_id`),
  KEY `idx_positions_product_code` (`product_Code`),
  CONSTRAINT `fk_positions_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
