DROP TABLE IF EXISTS `simulation_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `simulation_runs` (
  `run_id` bigint NOT NULL AUTO_INCREMENT,
  `scenario_id` int DEFAULT NULL,
  `as_of_datetime` datetime DEFAULT NULL,
  `simulation_date` datetime DEFAULT NULL,
  `horizon_days` int DEFAULT NULL,
  `run_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `records_processed` int DEFAULT NULL,
  `error_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `executed_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`run_id`),
  KEY `idx_runs_scenario` (`scenario_id`),
  CONSTRAINT `fk_runs_scenario` FOREIGN KEY (`scenario_id`) REFERENCES `scenarios` (`scenario_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
